$tools = "e:\openvela\contest2026_313_bianyuanxingzhe\tools\drivers"
New-Item -ItemType Directory -Force -Path $tools | Out-Null
# Try download CH343 and CH341 packages from wch.cn
$urls = @(
  @{ name='CH343SER.ZIP'; url='https://www.wch.cn/downloads/file/390.html' },
  @{ name='CH341SER.EXE'; url='https://www.wch.cn/downloads/file/5.html' }
)
# Direct zip links commonly used:
$dl = @(
  'https://www.wch.cn/download/file?fileid=390',
  'https://cdn.wch-ic.com/download/CH343SER.ZIP',
  'https://www.wch-ic.com/download/file?id=390'
)
# Use gh/curl style known mirrors
$targets = @(
  @{ out='CH343SER.ZIP'; url='https://www.wch.cn/downloads/CH343SER_ZIP.html' }
)

# Fetch actual download via known path from WCH
try {
  Invoke-WebRequest -Uri 'https://www.wch.cn/download/CH343SER_ZIP.html' -OutFile (Join-Path $tools 'page.html') -UseBasicParsing -MaximumRedirection 5
  Select-String -Path (Join-Path $tools 'page.html') -Pattern 'href=.*\.(zip|ZIP|exe|EXE)' | Select-Object -First 20
} catch { $_.Exception.Message }

try {
  Invoke-WebRequest -Uri 'http://www.wch.cn/downloads/CH343SER_ZIP.html' -OutFile (Join-Path $tools 'page2.html') -UseBasicParsing
  Select-String -Path (Join-Path $tools 'page2.html') -Pattern 'download|zip|file' | Select-Object -First 30
} catch { "page2: $($_.Exception.Message)" }

$tools = "e:\openvela\contest2026_313_bianyuanxingzhe\tools\drivers"
$candidates = @(
  'https://github.com/WCHSoftGroup/ch343ser_linux/releases',
  'https://cdn.wch-ic.com/downloads/CH343SER.ZIP',
  'https://www.wch-ic.com/downloads/CH343SER.ZIP',
  'https://file.wch.cn/download/download_soft/CH343SER.ZIP',
  'https://www.wch.cn/download/file?file=CH343SER.ZIP'
)
foreach ($u in $candidates) {
  try {
    $out = Join-Path $tools ('try_' + [IO.Path]::GetFileName($u.Split('?')[0]))
    Write-Host "TRY $u"
    Invoke-WebRequest -Uri $u -OutFile $out -UseBasicParsing -TimeoutSec 20
    Write-Host "OK size=$((Get-Item $out).Length)"
  } catch {
    Write-Host "FAIL $($_.Exception.Message)"
  }
}
Get-ChildItem $tools | Format-Table Name, Length

# Repair / re-enable CH343 device
$dev = Get-PnpDevice | Where-Object { $_.FriendlyName -match 'CH343' }
$dev | Format-List FriendlyName, Status, InstanceId, Class
foreach ($d in $dev) {
  try {
    Disable-PnpDevice -InstanceId $d.InstanceId -Confirm:$false -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 1
    Enable-PnpDevice -InstanceId $d.InstanceId -Confirm:$false -ErrorAction SilentlyContinue
    Write-Host "Toggled $($d.InstanceId)"
  } catch { Write-Host $_.Exception.Message }
}
Start-Sleep -Seconds 2
Get-PnpDevice | Where-Object { $_.FriendlyName -match 'CH34' } | Format-Table Status, FriendlyName -AutoSize

# Open official driver pages for user install
Start-Process 'http://www.wch.cn/downloads/CH343SER_ZIP.html'
Start-Process 'http://www.wch.cn/downloads/CH341SER_EXE.html'
Start-Process 'devmgmt.msc'

# pnputil enum
pnputil /enum-devices /class Ports 2>&1 | Select-String -Pattern 'CH34|1A86|Status|Instance' | Select-Object -First 40

# Try open both ports briefly
function Test-Com($port, $baud) {
  try {
    $sp = New-Object System.IO.Ports.SerialPort $port, $baud, 'None', 8, 'One'
    $sp.ReadTimeout = 300
    $sp.DtrEnable = $false
    $sp.RtsEnable = $false
    $sp.Open()
    Start-Sleep -Milliseconds 400
    $n = $sp.BytesToRead
    $data = if ($n -gt 0) { $sp.ReadExisting() } else { '' }
    $sp.Close(); $sp.Dispose()
    "[OK] $port baud=$baud open=True bytes=$($data.Length)"
  } catch {
    "[FAIL] $port baud=$baud $($_.Exception.Message)"
  }
}
Test-Com COM8 115200
Test-Com COM8 1000000
Test-Com COM7 1000000
Test-Com COM7 115200

# Download CH343 Windows driver from mirror if possible
$tools = "e:\openvela\contest2026_313_bianyuanxingzhe\tools\drivers"
New-Item -ItemType Directory -Force -Path $tools | Out-Null
$zip = Join-Path $tools 'CH343SER.ZIP'
# community mirror sometimes used
$mirrors = @(
  'https://github.com/nodemcu/nodemcu-devkit/raw/master/Drivers/CH341SER.EXE',
  'https://github.com/adrianmihalko/ch340g-ch34g-ch34x-mac-os-x-driver/raw/master/CH34x_Install_V1_4.pkg'
)
foreach ($m in @('https://cdn.jsdelivr.net/gh/WCHSoftGroup/ch34xser_linux@main/README.md')) {
  try { Invoke-WebRequest $m -OutFile (Join-Path $tools 'probe.txt') -TimeoutSec 15 -UseBasicParsing; 'jsdelivr ok' } catch { "mirror fail" }
}

# Full CH343 / COM7 diagnostic
Write-Host '=== PnP devices matching CH343 / SER / COM7 ==='
Get-PnpDevice | Where-Object {
  $_.FriendlyName -match 'CH343|CH34|COM7|Enhanced-SERIAL|USB.?Serial|WCH' -or
  $_.InstanceId -match 'VID_1A86|VID_1a86'
} | Format-Table Status, Class, FriendlyName, InstanceId -AutoSize

Write-Host '=== COM port registry ==='
Get-ItemProperty 'HKLM:\HARDWARE\DEVICEMAP\SERIALCOMM' -ErrorAction SilentlyContinue | Format-List

Write-Host '=== SetupAPI recent CH343/COM7 errors (tail) ==='
$log = 'C:\Windows\INF\setupapi.dev.log'
if (Test-Path $log) {
  Select-String -Path $log -Pattern 'CH343|1A86|COM7|Enhanced-SERIAL' -SimpleMatch:$false | Select-Object -Last 40 | ForEach-Object { $_.Line }
}

Write-Host '=== Driver files for CH343 ==='
Get-ChildItem 'C:\Windows\System32\drivers' -Filter '*ch34*' -ErrorAction SilentlyContinue | Format-Table Name, Length, LastWriteTime
Get-ChildItem 'C:\Windows\System32\drivers' -Filter '*wch*' -ErrorAction SilentlyContinue | Format-Table Name, Length, LastWriteTime

Write-Host '=== Get-PnpDeviceProperty for CH343 ==='
$dev = Get-PnpDevice | Where-Object { $_.FriendlyName -match 'CH343' } | Select-Object -First 1
if ($dev) {
  Write-Host "Found: $($dev.FriendlyName) Status=$($dev.Status) InstanceId=$($dev.InstanceId)"
  Get-PnpDeviceProperty -InstanceId $dev.InstanceId | Where-Object {
    $_.KeyName -match 'Problem|Status|Driver|DeviceDesc|HardwareID|ConfigFlags|LastArrival'
  } | Format-Table KeyName, Data -AutoSize
  # Problem code
  $prob = Get-PnpDeviceProperty -InstanceId $dev.InstanceId -KeyName 'DEVPKEY_Device_ProblemCode' -ErrorAction SilentlyContinue
  $probStat = Get-PnpDeviceProperty -InstanceId $dev.InstanceId -KeyName 'DEVPKEY_Device_ProblemStatus' -ErrorAction SilentlyContinue
  Write-Host "ProblemCode=$($prob.Data) ProblemStatus=$($probStat.Data)"
} else {
  Write-Host 'No CH343 friendly name device found'
}

Write-Host '=== PnP Ports / CH34x ==='
Get-PnpDevice | Where-Object {
  $_.FriendlyName -match 'CH343|CH340|COM7|COM8|Enhanced-SERIAL|USB-SERIAL' -or
  $_.InstanceId -match 'VID_1A86'
