function Get-TextFromContent($content) {
  if ($null -eq $content) { return '' }
  $parts = @()
  foreach ($c in $content) {
    if ($c.type -eq 'text' -and $c.text) { $parts += [string]$c.text }
    elseif ($c -is [string]) { $parts += $c }
  }
  return ($parts -join "`n")
}

function Convert-CursorToContest($srcPath, $sessionId, $outPath, $teamId, $ghLogin) {
  $seq = 0
  $started = $null
  $last = $null
  $writer = New-Object System.IO.StreamWriter($outPath, $false, [Text.UTF8Encoding]::new($false))
  try {
    Get-Content -LiteralPath $srcPath -Encoding UTF8 | ForEach-Object {
      $line = $_.Trim()
      if (-not $line) { return }
      try { $ev = $line | ConvertFrom-Json } catch { return }

      $role = $ev.role
      $ts = $null
      # Cursor may not have top-level ts; try extract from text timestamp tags later
      if ($ev.timestamp) { $ts = [string]$ev.timestamp }
      elseif ($ev.ts) { $ts = [string]$ev.ts }

      if ($role -eq 'user' -or $role -eq 'assistant') {
        $msg = $ev.message
        $content = $null
        if ($msg -and $msg.content) { $content = $msg.content }
        $text = Get-TextFromContent $content

        # Extract timestamp from <timestamp>...</timestamp> if present
        if ($text -match '<timestamp>([^<]+)</timestamp>') {
          $rawTs = $Matches[1].Trim()
          try {
            $dt = [datetime]::Parse($rawTs)
            $ts = $dt.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ')
          } catch {}
        }
        if (-not $ts) { $ts = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ') }
        if (-not $started) { $started = $ts }
        $last = $ts

        # Strip wrapper tags lightly for readability but keep content
        $clean = $text -replace '(?s)<timestamp>.*?</timestamp>\s*',''
        $clean = $clean -replace '(?s)<user_query>\s*','' -replace '(?s)\s*</user_query>',''
        if ($clean.Length -gt 200000) { $clean = $clean.Substring(0,200000) + "`n...[truncated]" }

        $obj = [ordered]@{
          schema_version = '1.0'
          session_id = $sessionId
          team_id = $teamId
          github_login = $ghLogin
          tool = 'cursor'
          seq = $seq
          ts = $ts
          role = $role
          model = if ($role -eq 'assistant') { 'cursor-grok-4.5' } else { $null }
          text = $clean
          source = 'cursor-agent-transcript'
        }
        # remove null model for user
        if ($role -eq 'user') { $obj.Remove('model') }
        $writer.WriteLine(($obj | ConvertTo-Json -Compress -Depth 8))
        $seq++

        # Emit tool events from assistant content
        if ($content) {
          foreach ($c in $content) {
            if ($c.type -eq 'tool_use') {
              $toolTs = $ts
              $tin = $c.input
              $inObj = $tin
              try {
                if ($tin) {
                  $inJson = ($tin | ConvertTo-Json -Compress -Depth 6)
                  if ($inJson.Length -gt 50000) { $inObj = @{ truncated = $true; preview = $inJson.Substring(0,50000) } }
                }
              } catch { $inObj = @{ note = 'input_serialize_failed' } }
              $tobj = [ordered]@{
                schema_version = '1.0'
                session_id = $sessionId
                team_id = $teamId
                github_login = $ghLogin
                tool = 'cursor'
                seq = $seq
                ts = $toolTs
                role = 'tool'
                tool_name = [string]$c.name
                tool_call_id = [string]$c.id
                input = $inObj
                output = @{ status = 'recorded_in_cursor_transcript' }
                source = 'cursor-agent-transcript'
              }
              $writer.WriteLine(($tobj | ConvertTo-Json -Compress -Depth 10))
              $seq++
            }
          }
        }
      }
      elseif ($ev.type -eq 'turn_ended') {
        # skip or mark
      }
    }
  } finally {
    $writer.Close()
  }
  return @{ event_count = $seq; started_at = $started; last_event_at = $last }
}

