/****************************************************************************
 * edge_walker: LD2451 frame parse + local threshold decision (host/unit-testable)
 *
 * Frame markers (HLK LD2451 UART proto): F4 F3 F2 F1 ... F8 F7 F6 F5
 * MVP decision: approaching && range_m <= THRESHOLD_M -> ALERT
 ****************************************************************************/

#ifndef EDGE_WALKER_LD2451_H
#define EDGE_WALKER_LD2451_H

#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

#define EW_LD2451_HDR0 0xF4
#define EW_LD2451_HDR1 0xF3
#define EW_LD2451_HDR2 0xF2
#define EW_LD2451_HDR3 0xF1
#define EW_LD2451_TAIL0 0xF8
#define EW_LD2451_TAIL1 0xF7
#define EW_LD2451_TAIL2 0xF6
#define EW_LD2451_TAIL3 0xF5

#ifndef EW_RANGE_ALERT_M
#define EW_RANGE_ALERT_M 15.0f
#endif

typedef enum {
  EW_ALERT_NONE = 0,
  EW_ALERT_WARN = 1,
  EW_ALERT_CRIT = 2
} ew_alert_level_t;

typedef struct {
  float range_m;
  float speed_mps; /* positive = approaching convention for MVP */
  bool approaching;
  bool valid;
} ew_track_t;

typedef struct {
  ew_alert_level_t level;
  float range_m;
  float speed_mps;
  bool approaching;
  const char *reason;
} ew_decision_t;

/* Feed raw UART bytes; returns true when a full frame was consumed into out. */
bool ew_ld2451_feed(const uint8_t *data, unsigned len, ew_track_t *out);

/* Local threshold — NOT LLM. */
ew_decision_t ew_decide(const ew_track_t *track);

/* Hardware abstraction; board impl may beep / LCD / LED. Host stub = printf. */
void alert_output(ew_alert_level_t level, const char *reason);

#ifdef __cplusplus
}
#endif

#endif /* EDGE_WALKER_LD2451_H */

/****************************************************************************
 * Minimal LD2451 stream parser + decision (skeleton for F role)
 *
 * NOTE: Target field layout must be locked against HLK protocol V1.03 PDF.
 * This file provides framing + decision; payload decode is marked TODO until
 * the team freezes the byte offsets from a captured frame.
 ****************************************************************************/

#include "ew_ld2451.h"

#include <stdio.h>
#include <string.h>

enum {
  ST_HDR0 = 0,
  ST_HDR1,
  ST_HDR2,
  ST_HDR3,
  ST_BODY,
  ST_TAIL0,
  ST_TAIL1,
  ST_TAIL2,
  ST_TAIL3
};

#define EW_MAX_BODY 128

static int g_st = ST_HDR0;
static uint8_t g_body[EW_MAX_BODY];
static unsigned g_body_len;
static unsigned g_expect_body; /* 0 = unknown length mode: accumulate until tail */

static bool body_looks_like_tail_start(uint8_t b)
{
  return b == EW_LD2451_TAIL0;
}

/* Placeholder decode — replace with V1.03 field map after capture. */
static bool decode_body(const uint8_t *body, unsigned len, ew_track_t *out)
{
  if (out == NULL || len < 4) {
    return false;
  }

  memset(out, 0, sizeof(*out));
  /* TODO(F): map distance/speed/direction from protocol PDF.
   * Keep a conservative invalid until real offsets are confirmed. */
  out->valid = false;
  out->range_m = 0.0f;
  out->speed_mps = 0.0f;
  out->approaching = false;

  (void)body;
  return false;
}

bool ew_ld2451_feed(const uint8_t *data, unsigned len, ew_track_t *out)
{
  bool got = false;

  if (data == NULL || out == NULL) {
    return false;
  }

  for (unsigned i = 0; i < len; i++) {
    uint8_t b = data[i];
    switch (g_st) {
      case ST_HDR0:
        g_st = (b == EW_LD2451_HDR0) ? ST_HDR1 : ST_HDR0;
        break;
      case ST_HDR1:
        g_st = (b == EW_LD2451_HDR1) ? ST_HDR2 : ST_HDR0;
        break;
      case ST_HDR2:
        g_st = (b == EW_LD2451_HDR2) ? ST_HDR3 : ST_HDR0;
        break;
      case ST_HDR3:
        if (b == EW_LD2451_HDR3) {
          g_st = ST_BODY;
          g_body_len = 0;
          g_expect_body = 0;
        } else {
          g_st = ST_HDR0;
        }
        break;
      case ST_BODY:
        if (body_looks_like_tail_start(b)) {
          g_st = ST_TAIL1;
        } else if (g_body_len < EW_MAX_BODY) {
          g_body[g_body_len++] = b;
        } else {
          g_st = ST_HDR0; /* overflow resync */
        }
        break;
      case ST_TAIL1:
        g_st = (b == EW_LD2451_TAIL1) ? ST_TAIL2 : ST_HDR0;
        break;
      case ST_TAIL2:
        g_st = (b == EW_LD2451_TAIL2) ? ST_TAIL3 : ST_HDR0;
        break;
      case ST_TAIL3:
        if (b == EW_LD2451_TAIL3) {
          if (decode_body(g_body, g_body_len, out)) {
            got = true;
          }
        }
        g_st = ST_HDR0;
        break;
      default:
        g_st = ST_HDR0;
        break;
    }
  }

  return got;
}

ew_decision_t ew_decide(const ew_track_t *track)
{
  ew_decision_t d;

  memset(&d, 0, sizeof(d));
  d.level = EW_ALERT_NONE;
  d.reason = "idle";

  if (track == NULL || !track->valid) {
    d.reason = "invalid_track";
    return d;
  }

  d.range_m = track->range_m;
  d.speed_mps = track->speed_mps;
  d.approaching = track->approaching;

  if (track->approaching && track->range_m <= EW_RANGE_ALERT_M) {
    d.level = (track->range_m <= 8.0f) ? EW_ALERT_CRIT : EW_ALERT_WARN;
    d.reason = "approaching_within_threshold";
  } else {
    d.reason = "no_alert";
  }

  return d;
}

void alert_output(ew_alert_level_t level, const char *reason)
{
  const char *name = "NONE";
  if (level == EW_ALERT_WARN) {
    name = "WARN";
  } else if (level == EW_ALERT_CRIT) {
    name = "CRIT";
  }
  printf("[alert_output] level=%s reason=%s\n", name, reason ? reason : "");
}

