/****************************************************************************
 * 提醒出口（郑子轩主责）
 *
 * 全队冻结调用：alert_output(档位, 原因)
 * 王筠昊 / 韦政宇只调这个函数，不写蜂鸣/灯细节。
 ****************************************************************************/

#ifndef EDGE_WALKER_ALERT_OUTPUT_H
#define EDGE_WALKER_ALERT_OUTPUT_H

#ifdef __cplusplus
extern "C" {
#endif

typedef enum {
  EW_ALERT_NONE = 0,
  EW_ALERT_WARN = 1,
  EW_ALERT_CRIT = 2
} ew_alert_level_t;

/* 档位：0 静音，1 提醒，2 紧急。reason 可为 NULL。 */
void alert_output(ew_alert_level_t level, const char *reason);

#ifdef __cplusplus
}
#endif

#endif /* EDGE_WALKER_ALERT_OUTPUT_H */

/****************************************************************************
 * 提醒出口实现（郑子轩）
 *
 * 1) 控制台一定打印一行（NSH / 串口能看见）
 * 2) 板上若有 /dev/pwm0，则按档位开蜂鸣；没有则跳过，不算失败
 ****************************************************************************/

#include "alert_output.h"

#include <stdio.h>

#ifdef __NuttX__
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <errno.h>
#ifdef CONFIG_PWM
#include <nuttx/timers/pwm.h>
#endif
#endif

static const char *level_name(ew_alert_level_t level)
{
  if (level == EW_ALERT_WARN) {
    return "WARN";
  }
  if (level == EW_ALERT_CRIT) {
    return "CRIT";
  }
  return "NONE";
}

#ifdef __NuttX__
#ifdef CONFIG_PWM
static void pwm_apply(ew_alert_level_t level)
{
  struct pwm_info_s info;
  int fd = open("/dev/pwm0", O_RDWR);
  if (fd < 0) {
    return;
  }

  if (level == EW_ALERT_NONE) {
    ioctl(fd, PWMIOC_STOP, 0);
    close(fd);
    return;
  }

  info.frequency = (level == EW_ALERT_CRIT) ? 2500 : 1800;
  info.duty = (level == EW_ALERT_CRIT) ? ((uint32_t)(0.6f * 65536.0f))
                                      : ((uint32_t)(0.35f * 65536.0f));
#ifdef CONFIG_PWM_NCHANNELS
  info.channels[0].channel = 1;
  info.channels[0].duty = info.duty;
#endif

  if (ioctl(fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)((uintptr_t)&info)) >= 0) {
    ioctl(fd, PWMIOC_START, 0);
  }
  close(fd);
}
#else
static void pwm_apply(ew_alert_level_t level)
{
  (void)level;
}
#endif
#endif

void alert_output(ew_alert_level_t level, const char *reason)
{
  printf("[alert_output] level=%s reason=%s\n",
         level_name(level),
         reason ? reason : "");
  fflush(stdout);

#ifdef __NuttX__
  pwm_apply(level);
#endif
}

