/****************************************************************************
 * 边缘行者主程序骨架（郑子轩）
 *
 * NSH:
 *   ew                 打开 /dev/ttyS1 循环读雷达并走判断→提醒
 *   ew alert warn      只测提醒出口（不需要雷达）
 *   ew alert crit
 *   ew alert none
 *   ew fake 10 2       假靠近：10 米、速度 2（正=靠近），测整条链
 ****************************************************************************/

#include "alert_output.h"
#include "ew_ld2451.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef __NuttX__
#include <fcntl.h>
#include <unistd.h>
#endif

#ifndef EW_RADAR_DEV
#define EW_RADAR_DEV "/dev/ttyS1"
#endif

static int cmd_alert(int argc, char **argv)
{
  ew_alert_level_t level = EW_ALERT_WARN;
  const char *reason = "manual_test";

  if (argc >= 3) {
    if (strcmp(argv[2], "none") == 0 || strcmp(argv[2], "0") == 0) {
      level = EW_ALERT_NONE;
    } else if (strcmp(argv[2], "crit") == 0 || strcmp(argv[2], "2") == 0) {
      level = EW_ALERT_CRIT;
    } else {
      level = EW_ALERT_WARN;
    }
  }
  if (argc >= 4) {
    reason = argv[3];
  }

  alert_output(level, reason);
  return 0;
}

static int cmd_fake(int argc, char **argv)
{
  ew_track_t t;
  ew_decision_t d;

  memset(&t, 0, sizeof(t));
  t.valid = true;
  t.range_m = (argc >= 3) ? (float)atof(argv[2]) : 10.0f;
  t.speed_mps = (argc >= 4) ? (float)atof(argv[3]) : 2.0f;
  t.approaching = (t.speed_mps > 0.0f);

  d = ew_decide(&t);
  printf("[ew] fake range=%.1fm speed=%.1f approaching=%d -> %s\n",
         t.range_m, t.speed_mps, (int)t.approaching, d.reason);
  alert_output(d.level, d.reason);
  return 0;
}

static int cmd_loop(void)
{
#ifdef __NuttX__
  uint8_t buf[64];
  ew_track_t track;
  int fd = open(EW_RADAR_DEV, O_RDONLY);
  if (fd < 0) {
    printf("[ew] open %s failed\n", EW_RADAR_DEV);
    return 1;
  }

  printf("[ew] reading %s, Ctrl-C to stop\n", EW_RADAR_DEV);
  for (;;) {
    int n = read(fd, buf, sizeof(buf));
    if (n <= 0) {
      usleep(20000);
      continue;
    }
    if (ew_ld2451_feed(buf, (unsigned)n, &track) && track.valid) {
      ew_decision_t d = ew_decide(&track);
      printf("[ew] range=%.1fm approaching=%d %s\n",
             d.range_m, (int)d.approaching, d.reason);
      alert_output(d.level, d.reason);
    }
  }
#else
  printf("[ew] host stub: use `ew fake 10 2` or `ew alert warn`\n");
#endif
  return 0;
}

int main(int argc, char *argv[])
{
  printf("edge_walker (Zheng / main)\n");
  printf("  radar dev: %s\n", EW_RADAR_DEV);

  if (argc >= 2 && strcmp(argv[1], "alert") == 0) {
    return cmd_alert(argc, argv);
  }
  if (argc >= 2 && strcmp(argv[1], "fake") == 0) {
    return cmd_fake(argc, argv);
  }
  if (argc >= 2 && (strcmp(argv[1], "-h") == 0 || strcmp(argv[1], "help") == 0)) {
    printf("usage:\n");
    printf("  ew                 read radar on %s\n", EW_RADAR_DEV);
    printf("  ew alert warn|crit|none [reason]\n");
    printf("  ew fake [range_m] [speed]\n");
    return 0;
  }

  return cmd_loop();
}

